(function(root){
'use strict';
root.createPatientInvitation=function(ctx){
 const {$,esc,toast}=ctx,C=root.InvitationCore;let stayId=null,draft={},photoUrl='',rawText='',busy=false,linkData=null,formDraft={},generation=0;
 const options=(rows,v)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===v?'selected':''}>${esc(label)}</option>`).join('');
 const field=(name,label,type='text',value='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['firstName','lastName','birthDate'].includes(name)?'required':''} maxlength="180"></label>`;
 function clearPhoto(){if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl='';rawText='';generation++}
 function render(){if(stayId===null)stayId=ctx.current()?.id||'';$('#title').textContent='Questionnaire depuis une photo';$('#stats').hidden=true;$('#new').hidden=true;document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='questionnaireSend'));$('#workspace').innerHTML='<section class="panel"><div class="content" id="invitation-workspace"></div></section>';draw()}
 function draw(){const host=$('#invitation-workspace');if(!host)return;const teams=ctx.teams();const saved=ctx.patients.find(p=>p.id===stayId)?.invitationContact?.contact||{};const v={...saved,...draft,...formDraft};
 host.innerHTML=`<p class="eyebrow">PRÉPARER LE QUESTIONNAIRE PATIENT</p><h2>Photo du profil Doctolib</h2><p>Importez une photo ou une capture, puis vérifiez l’identité et le destinataire avant de préparer le message. L’image est lue dans ce navigateur et n’est pas enregistrée sur le serveur.</p><p class="notice warn">Prototype : profils fictifs uniquement. Le lien patient permet de remplir uniquement le questionnaire invité, sans compte professionnel. L’envoi par SMS ou e-mail (Brevo) ne part qu’après votre clic, vers les coordonnées vérifiées du séjour.</p><div class="invitation-grid"><section><h3>Photo à lire</h3><label class="invitation-upload">Choisir une photo ou capture<input id="doctolib-photo" type="file" accept="image/jpeg,image/png,image/webp" ${busy?'disabled':''}></label><label class="invitation-upload">Prendre une photo<input id="doctolib-camera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" ${busy?'disabled':''}></label><p class="muted">JPEG, PNG ou WebP, 12 Mo maximum. Vous pouvez aussi coller une capture dans cette zone.</p><div id="doctolib-paste" tabindex="0" class="invitation-preview">${photoUrl?`<img src="${esc(photoUrl)}" alt="Photo du profil à comparer aux champs extraits">`:'La photo apparaîtra ici.'}</div><div class="actions"><button type="button" class="secondary" id="doctolib-read" ${!photoUrl||busy?'disabled':''}>Lire la photo</button><button type="button" class="secondary" id="doctolib-clear" ${busy?'disabled':''}>Effacer la photo</button></div><p id="doctolib-progress" role="status">${busy?'Lecture en cours…':''}</p>${rawText?`<details><summary>Texte détecté, à vérifier</summary><pre class="invitation-raw">${esc(rawText)}</pre></details>`:''}</section><section><h3>Vérifier l’identité et les coordonnées</h3><form id="invitation-contact"><div class="formgrid"><label class="wide">Séjour destinataire<select name="stay">${options([['','Créer un nouveau séjour fictif'],...ctx.patients.map(p=>[p.id,p.id+' · '+[p.identity?.lastName,p.identity?.firstName].filter(Boolean).join(' ')])],stayId)}</select></label>${!stayId?`<label class="wide">Équipe du nouveau séjour<select name="team" required>${options([['','Choisir une équipe'],...teams.map(t=>[t.id,t.label])],v.team||'')}</select></label>`:''}${field('lastName','Nom de naissance','text',v.lastName)}${field('firstName','Premier prénom','text',v.firstName)}${draft.usedName&&draft.usedName!==v.lastName?`<p class="notice wide"><span>Nom d’usage lu sur la photo : <strong>${esc(draft.usedName)}</strong>. L’identité utilise le nom de naissance ; vérifiez-le sur la photo.</span></p>`:''}${rawText&&(!draft.lastName||!draft.firstName)?'<p class="notice warn wide"><span>Nom ou prénom non reconnu : recopiez-les depuis la photo.</span></p>':''}${field('birthDate','Date de naissance','date',v.birthDate)}${field('email','E-mail du destinataire','email',v.email)}${field('phone','Téléphone du destinataire','tel',v.phone)}</div><p class="muted">Une photo ne garantit ni l’identité ni l’exactitude des coordonnées. Complétez les champs manquants et corrigez les caractères mal lus.</p><label class="check"><input name="confirmed" type="checkbox" required> J’ai vérifié la photo, l’identité du séjour et les coordonnées du destinataire.</label><p class="invitation-error" role="alert"></p><button class="primary" ${busy||!ctx.canPrepare()?'disabled':''}>Préparer le lien et le message</button></form></section></div><section id="invitation-result" aria-live="polite"></section>`;
 const form=$('#invitation-contact');form.elements.stay.onchange=e=>{formDraft=Object.fromEntries(new FormData(form));stayId=e.target.value;linkData=null;draw()};form.oninput=e=>{if(e.target.name!=='confirmed'){form.elements.confirmed.checked=false;linkData=null;$('#invitation-result').textContent=''}};
 form.onsubmit=prepare;
 for(const id of ['doctolib-photo','doctolib-camera'])$('#'+id).onchange=e=>{if(e.target.files[0])loadPhoto(e.target.files[0])};
 $('#doctolib-paste').onpaste=e=>{const image=[...(e.clipboardData?.files||[])].find(f=>f.type.startsWith('image/'));if(image){e.preventDefault();loadPhoto(image)}};
 $('#doctolib-clear').onclick=()=>{clearPhoto();draw()};$('#doctolib-read').onclick=()=>recognize();if(linkData)showLink();
 }
 async function loadPhoto(file){if(busy)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){toast('Choisissez une image JPEG, PNG ou WebP de moins de 12 Mo.');return}formDraft={};draft={};linkData=null;clearPhoto();photoUrl=URL.createObjectURL(file);draw();await recognize()}
 async function recognize(){if(!photoUrl||busy)return;busy=true;const expected=++generation;draw();let worker;
 try{
  if(!root.Tesseract)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/ocr/tesseract.min.js';script.onload=resolve;script.onerror=()=>reject(Error('Moteur de lecture indisponible.'));document.head.append(script)});
  const bitmap=await createImageBitmap(await (await fetch(photoUrl)).blob());const canvas=C.prepareCanvas(bitmap,document);bitmap.close();
  worker=await root.Tesseract.createWorker('fra',1,{workerPath:location.origin+'/ocr/worker.min.js',corePath:location.origin+'/ocr/tesseract-core-lstm.wasm.js',langPath:location.origin+'/ocr',workerBlobURL:false,cacheMethod:'none',logger:m=>{const el=$('#doctolib-progress');if(el)el.textContent='Lecture locale · '+Math.round((m.progress||0)*100)+' %'}});
  await worker.setParameters(C.OCR_PARAMS);const result=await worker.recognize(canvas);if(expected!==generation)return;rawText=result.data.text||'';draft=C.parseProfile(rawText);formDraft={};
 }catch(e){loadError(e.message||'Lecture impossible. Renseignez les champs manuellement.')}finally{await worker?.terminate();busy=false;if(expected===generation){draw();const el=$('#doctolib-progress');if(el)el.textContent=rawText?'Lecture terminée. Vérifiez et complétez tous les champs.':'Texte non exploitable : vous pouvez renseigner les champs manuellement.'}}}
 function loadError(message){toast(message);const el=$('#doctolib-progress');if(el)el.textContent=message}
 async function prepare(e){e.preventDefault();if(!ctx.canPrepare()||busy)return;const form=e.currentTarget,v=Object.fromEntries(new FormData(form)),contact=C.contact(v),error=C.contactError(contact);const errorNode=form.querySelector('[role=alert]');if(error){errorNode.textContent=error;return}if(v.confirmed!=='on'){errorNode.textContent='Confirmez la vérification des coordonnées.';return}
 let stay=ctx.patients.find(p=>p.id===v.stay);if(stay?.identity?.lastName&&stay.identity.firstName&&stay.identity.birthDate&&!C.matchesIdentity(stay.identity,contact)){errorNode.textContent='L’identité diffère du séjour sélectionné. Corrigez les champs ou choisissez le bon séjour.';return}
 if(!stay){const duplicate=ctx.patients.find(p=>C.matchesIdentity(p.identity||{},contact));if(duplicate){stayId=duplicate.id;formDraft=contact;draw();$('#invitation-contact [role=alert]').textContent='Un séjour correspond déjà à cette identité. Vérifiez ce séjour puis confirmez à nouveau.';return}if(!v.team){errorNode.textContent='Choisissez une équipe pour le nouveau séjour.';return}stay=ctx.create(contact,v.team);stayId=stay.id;}
 const button=form.querySelector('button.primary');button.disabled=true;
 try{stay.invitationContact={contact,confirmed:true,verifiedBy:ctx.access().profile.user_id,verifiedAt:new Date().toISOString(),source:photoUrl?'Photo Doctolib relue':'Saisie manuelle vérifiée'};await ctx.save();const response=await fetch('/api/workspace/questionnaire/invite',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stay:stay.id,contact,confirmed:true})});const data=await response.json();if(!response.ok)throw Error(data.error||'Préparation indisponible.');linkData={...data,contact};formDraft=contact;showLink();}
 catch(error){errorNode.textContent=error.message}finally{button.disabled=false}
 }
 function showLink(){const out=$('#invitation-result');if(!out||!linkData)return;const {link,expiresAt,contact}=linkData,brevo=linkData.messaging||{},canSms=brevo.sms&&!!contact.phone,canEmail=brevo.email&&!!contact.email;const message='Bonjour, merci de remplir votre questionnaire avant votre venue : '+link+'\nLien valable 48 heures, une seule utilisation.';out.innerHTML=`<h3>Lien et message préparés</h3><p class="notice warn">${canSms||canEmail?'Rien n’est envoyé tant que vous n’avez pas cliqué sur un bouton d’envoi.':'Aucun message n’a été envoyé.'} Le lien donne accès au questionnaire invité pendant 48 heures et ne peut être utilisé qu’une fois. Transmettez-le uniquement au destinataire vérifié.</p><p>Destinataire vérifié : <strong>${esc(contact.firstName+' '+contact.lastName)}</strong><br>${esc(contact.email)} · ${esc(contact.phone)}</p><p>Expiration : ${esc(new Date(expiresAt).toLocaleString('fr-FR'))}</p><textarea id="invitation-message" rows="6" readonly>${esc(message)}</textarea>${canSms||canEmail?`<div class="actions" id="brevo-actions">${canSms?'<button class="primary" data-send="sms">Envoyer par SMS</button>':''}${canEmail?'<button class="primary" data-send="email">Envoyer par e-mail</button>':''}${canSms&&canEmail?'<button class="secondary" data-send="sms,email">Envoyer les deux</button>':''}</div><p class="muted">Envoi via Brevo au destinataire vérifié ci-dessus. Le message contient uniquement le lien, sans information médicale. Chaque envoi est tracé.</p><p id="brevo-status" role="status"></p>`:''}<div class="actions"><button class="secondary" id="invitation-copy">Copier le message</button><a class="secondary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Tester le questionnaire</a>${contact.email&&!canEmail?`<a class="secondary" href="mailto:${encodeURIComponent(contact.email)}?subject=${encodeURIComponent('Questionnaire avant votre consultation')}&body=${encodeURIComponent(message)}">Ouvrir le courriel de démonstration</a>`:''}${/^\+33[67]/.test(contact.phone)&&!canSms?`<a class="secondary" href="sms:${esc(contact.phone)}${/iPhone|iPad/.test(navigator.userAgent)?'&':'?'}body=${encodeURIComponent(message)}">Ouvrir le SMS de démonstration</a>`:''}</div>`;out.querySelectorAll('[data-send]').forEach(b=>b.onclick=()=>send(b.dataset.send.split(',')));$('#invitation-copy').onclick=async()=>{try{await navigator.clipboard.writeText(message);toast('Message copié')}catch{$('#invitation-message').focus();$('#invitation-message').select();toast('Sélectionnez puis copiez le message.')}};out.scrollIntoView({block:'start',behavior:'smooth'})}
 async function send(channels){if(!linkData)return;const status=$('#brevo-status'),buttons=[...document.querySelectorAll('#brevo-actions button')],names={sms:'le SMS',email:'l’e-mail'};if(!confirm('Envoyer '+channels.map(c=>names[c]).join(' et ')+' à '+linkData.contact.firstName+' '+linkData.contact.lastName+' ?'))return;buttons.forEach(b=>b.disabled=true);status.textContent='Envoi en cours…';
 try{const token=new URLSearchParams(new URL(linkData.link).hash.slice(1)).get('invitation');const response=await fetch('/api/workspace/questionnaire/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stay:stayId,token,channels})});const data=await response.json();if(!data.results)throw Error(data.error||'Envoi indisponible.');
  status.innerHTML=data.results.map(r=>r.sent?'✓ '+(r.channel==='sms'?'SMS':'E-mail')+' envoyé à '+esc(r.to)+' à '+esc(new Date(r.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})):'✗ '+esc(r.error)).join('<br>');toast(data.results.every(r=>r.sent)?'Message envoyé':'Envoi incomplet : voir le détail');}
 catch(e){status.textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}}
 window.addEventListener('beforeunload',clearPhoto);return {render};
};
})(typeof window!=='undefined'?window:globalThis);
